/// <summary>
/// Central store numbersequence module
/// </summary>
internal final class NDXNumberSeqCSDId extends NumberSeqApplicationModule
{
    public NumberSeqReference                      numberSeqReference;
    public boolean                                 runExecuteDirect;
    public TmpIdRef                                tmpIdRef;
    public NumberSeqScope                          scope;
    public NumberSeqApplicationModule              numberSeqApplicationModule;
    public container                               numberSequenceModules;

}

Method.Source:
public void loadModule()
{
    NumberSeqDatatype datatype = NumberSeqDatatype::construct();
    datatype.parmDatatypeId(extendedTypeNum(NDXCSDId));
    datatype.parmReferenceHelp(literalStr("@NDX:NDXCSDIdNumSeq"));
    datatype.parmWizardIsContinuous(false);
    datatype.parmWizardIsManual(NoYes::No);
    datatype.parmWizardIsChangeDownAllowed(NoYes::No);
    datatype.parmWizardIsChangeUpAllowed(NoYes::No);
    datatype.parmSortField(1);
    datatype.parmWizardLowest(1);
    datatype.parmWizardHighest(999999);

    this.create(datatype);
}

/// <summary>
/// Add module of number sequences to map
/// </summary>
/// <param name = "numberSeqModuleNamesMap">Map of number sequences</param>
[SubscribesTo(classStr(NumberSeqGlobal), delegateStr(NumberSeqGlobal, buildModulesMapDelegate))]
public static void NumberSeqGlobal_buildModulesMapDelegate(Map numberSeqModuleNamesMap)
{
    NumberSeqGlobal::addModuleToMap(classnum(NDXNumberSeqCSDId), numberSeqModuleNamesMap);
}
